/* search */
$('#searchInput').addEventListener('input', async e => {
  const q = e.target.value.trim().toLowerCase();
  const box = $('#searchResults');
  if (!q) { box.classList.add('hidden'); box.innerHTML = ''; return; }
  if (!SEARCH_INDEX) {
    box.innerHTML = '<div class="result-row"><span class="rz">词库加载中…</span></div>';
    box.classList.remove('hidden');
    await ensureIndex();
    if (e.target.value.trim().toLowerCase() !== q) return;
  }
  const hits = [];
  for (const w of SEARCH_INDEX) { if (w.w.toLowerCase().startsWith(q)) hits.push(w); if (hits.length >= 20) break; }
  if (hits.length < 20) for (const w of SEARCH_INDEX) { const lw = w.w.toLowerCase(); if (!lw.startsWith(q) && lw.includes(q)) { hits.push(w); if (hits.length >= 20) break; } }
  box.innerHTML = hits.length
    ? hits.map(w => `<button class="result-row" data-word="${esc(w.w.toLowerCase())}" type="button"><span><span class="rw">${esc(w.w)}</span><div class="rz">${esc(cleanZh(w.zh).slice(0, 42))}</div></span></button>`).join('')
    : '<div class="result-row"><span class="rz">没找到这个词</span></div>';
  box.classList.remove('hidden');
  box.querySelectorAll('[data-word]').forEach(b => b.onclick = async () => { await ensureLookup(); openSheet(b.dataset.word); });
});

/* ---------- Scenario ---------- */
let curScene = null, stopSeq = null, zhHidden = false;
function renderSceneList() {
  $('#sceneDetail').classList.add('hidden');
  const list = $('#sceneList');
  list.classList.remove('hidden');
  const q = (($('#sceneSearch') || {}).value || '').trim().toLowerCase();
  const items = SCENES.map((sc, i) => ({ sc, i })).filter(({ sc }) => !q || (sc.title + ' ' + (sc.sub || '') + ' ' + (sc.keywords || '')).toLowerCase().includes(q));
  list.innerHTML = items.length
    ? items.map(({ sc, i }) => `<button class="scene-item glass" data-i="${i}" type="button"><span class="ic">${icon(sc.icon)}</span><span><div class="tt">${esc(sc.title)}</div><div class="ss">${esc(sc.sub)}</div></span><span class="cnt">${sc.sentences.length} 句 ›</span></button>`).join('')
    : '<p class="hint">没找到这个场景。换个词试试；或者直接在聊天里告诉我想学哪个场景，我现做一个场景包更新上来。</p>';
  list.querySelectorAll('.scene-item').forEach(b => b.onclick = () => openScene(+b.dataset.i));
}
$('#sceneSearch').addEventListener('input', renderSceneList);
function openScene(i) {
  curScene = SCENES[i]; zhHidden = false;
  $('#hideZhBtn').textContent = '遮住中文自测';
  $('#sceneList').classList.add('hidden');
  $('#sceneDetail').classList.remove('hidden');
  renderSentences(); window.scrollTo(0, 0);
}
function renderSentences() {
  const list = $('#sentList');
  list.innerHTML = curScene.sentences.map((s, i) => `<div class="sent glass" data-i="${i}"><span class="n">${i + 1}</span><div class="tx"><div class="e">${tokenize(s.en)}</div><div class="z" ${zhHidden ? 'style="visibility:hidden"' : ''}>${esc(s.zh)}</div></div><button class="speak-btn sm" data-speak="${esc(s.en)}" type="button">${icon('speaker')}</button></div>`).join('');
  bindSpeak(list);
}
$('#hideZhBtn').addEventListener('click', () => {
  zhHidden = !zhHidden;
  $('#hideZhBtn').textContent = zhHidden ? '显示中文' : '遮住中文自测';
  renderSentences();
});
function setPlayBtn(playing) { $('#playAllBtn').innerHTML = icon(playing ? 'stop' : 'play') + '<span>' + (playing ? '停止连读' : '整场连读') + '</span>'; }
$('#playAllBtn').addEventListener('click', () => {
  if (stopSeq) { stopSeq(); stopSeq = null; setPlayBtn(false); return; }
  const rows = $$('#sentList .sent');
  setPlayBtn(true);
  stopSeq = speakSeq(curScene.sentences.map(s => s.en), i => {
    rows.forEach(r => r.classList.toggle('now', +r.dataset.i === i));
    if (i >= 0 && rows[i]) rows[i].scrollIntoView({ block: 'center', behavior: 'smooth' });
    if (i === -1) { stopSeq = null; setPlayBtn(false); }
  });
});

/* ---------- Phrase ---------- */
let curPack = null;
function renderPhraseList() {
  $('#phraseDetail').classList.add('hidden');
  const list = $('#phraseList');
  list.classList.remove('hidden');
  list.innerHTML = PHRASES.map((p, i) => {
    const learned = p.phrases.filter((_, j) => srs['p:' + p.id + ':' + j]).length;
    return `<button class="scene-item glass" data-i="${i}" type="button"><span class="ic">${icon(p.icon)}</span><span><div class="tt">${esc(p.title)}</div><div class="ss">${esc(p.sub)}</div></span><span class="cnt">${learned ? '已学 ' + learned + '/' : ''}${p.phrases.length} 句 ›</span></button>`;
  }).join('');
  list.querySelectorAll('.scene-item').forEach(b => b.onclick = () => openPack(+b.dataset.i));
}
function openPack(i) {
  curPack = PHRASES[i];
  $('#phraseList').classList.add('hidden');
  $('#phraseDetail').classList.remove('hidden');
  const rows = $('#phraseRows');
  rows.innerHTML = curPack.phrases.map(p => `<div class="phrase-row glass"><div class="row-flex"><div class="tx"><div class="pe">${tokenize(p.en)}</div><div class="pz">${esc(p.zh)}</div></div><button class="speak-btn sm" data-speak="${esc(p.en)}" type="button">${icon('speaker')}</button></div><div class="px">${tokenize(p.ex.en)}<div class="pxz">${esc(p.ex.zh)}</div></div></div>`).join('');
  bindSpeak(rows);
  window.scrollTo(0, 0);
}
$('#learnPackBtn').addEventListener('click', () => {
  if (!curPack) return;
  const all = curPack.phrases.map((_, j) => ({ t: 'p', pack: curPack, idx: j }));
  let off = 0;
  const provider = {
    take() { const s = all.slice(off, off + SET_SIZE); off += s.length; return s.length ? s : null; },
    more() { return off < all.length; }
  };
  startSession('learn', provider, '短语 · ' + curPack.title);
});

/* ---------- Review ---------- */
function fmtTime(ts) {
  return new Date(ts).toLocaleString('zh-CN', { month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit' });
}
function renderReview() {
  const due = dueItems();
  const dw = due.filter(d => d.t === 'w').length, dp = due.length - dw;
  $('#reviewCount').textContent = due.length;
  $('#reviewSub').textContent = due.length ? `个到期要复习（单词 ${dw} · 短语 ${dp}）` : '现在没有到期的复习';
  $('#reviewStart').disabled = !due.length;
  let next = Infinity;
  for (const e of Object.values(srs)) if (e.due < next) next = e.due;
  $('#nextDueHint').textContent = !isFinite(next) ? '还没开始学：先去 Learn 学第一组词吧。'
    : due.length ? '' : '下一个复习：' + fmtTime(next);
  const keys = Object.keys(srs);
  $('#statWords').textContent = keys.filter(k => k.startsWith('w:')).length;
  $('#statPhrases').textContent = keys.filter(k => k.startsWith('p:')).length;
  $('#statMastered').textContent = Object.values(srs).filter(e => e.r >= 3 && e.iv >= 7).length;
  $('#statFav').textContent = favSet.size;
}
$('#reviewStart').addEventListener('click', () => {
  const provider = {
    take() { const d = dueItems().slice(0, SET_SIZE); return d.length ? d : null; },
    more() { return dueItems().length > 0; }
  };
  startSession('review', provider, '复习');
});
$('#resetBtn').addEventListener('click', () => {
  if (!confirm('确定要清空全部学习进度和收藏吗？')) return;
  srs = {}; persistSrs();
  dayRec = { date: todayStr(), introduced: 0 }; persistDay();
  favSet.clear(); persistFav();
  renderReview(); renderLearnHome(); renderCollection();
  alert('已清空。');
});

/* ---------- Collection ---------- */
function renderCollection() {
  const list = $('#favList');
  const words = [...favSet].sort();
  $('#favEmpty').classList.toggle('hidden', words.length > 0);
  $('#favLearnBtn').disabled = !words.length;
  $('#favLearnBtn').textContent = words.length ? `学习收藏词（${words.length}）` : '学习收藏词';
  list.innerHTML = words.map(w => {
    const r = resolveWord(w) || { ph: '', zh: '' };
    return `<div class="fav-row glass" data-word="${esc(w)}"><div class="tx"><div class="fw">${esc(w)}</div><div class="fz">${esc(cleanZh(r.zh).slice(0, 40))}</div></div><button class="speak-btn sm" data-speak="${esc(w)}" type="button">${icon('speaker')}</button><button class="star-btn on" data-unfav="${esc(w)}" type="button">${icon('starFill')}</button></div>`;
  }).join('');
  bindSpeak(list);
  list.querySelectorAll('[data-unfav]').forEach(b => b.onclick = e => { e.stopPropagation(); toggleFav(b.dataset.unfav); renderCollection(); syncCardStar(); updateSheetStar(); });
  list.querySelectorAll('.fav-row').forEach(r => r.onclick = () => openSheet(r.dataset.word));
}
$('#favLearnBtn').addEventListener('click', () => {
  const all = [...favSet].sort().filter(w => WORDMAP[w] || INDEXMAP[w]).map(w => ({ t: 'w', word: w }));
  let off = 0;
  const provider = {
    take() { const s = all.slice(off, off + SET_SIZE); off += s.length; return s.length ? s : null; },
    more() { return off < all.length; }
  };
  startSession('collection', provider, '收藏词');
});

/* ---------- rate toggle ---------- */
function renderRate() {
  $('#rateSlow').classList.toggle('on', rate < 0.85);
  $('#rateNorm').classList.toggle('on', rate >= 0.85);
}
$('#rateSlow').addEventListener('click', () => { rate = 0.75; localStorage.setItem('bw.rate', rate); renderRate(); });
$('#rateNorm').addEventListener('click', () => { rate = 0.92; localStorage.setItem('bw.rate', rate); renderRate(); });

/* ---------- boot ---------- */
(async function init() {
  [BOOKS, SCENES, PHRASES] = await Promise.all([
    loadJSON('data/books.json', []), loadJSON('data/scenes.json', []), loadJSON('data/phrases.json', []),
  ]);
  Object.values(wordCache).forEach(e => { WORDMAP[e.w.toLowerCase()] = e; });
  if (!bookMeta(curBook)) curBook = (BOOKS[0] || {}).id || 'ielts';
  await setBook(curBook, true);
  $$('[data-icon]').forEach(el => { el.innerHTML = icon(el.dataset.icon); });
  setPlayBtn(false);
  renderRate(); renderLearnHome();
  ensureIndex(); ensureLookup();
})();
